# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
# EKS-CLUSTER APPLICATIONS
# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

# ---------------------------------------------------------------------------------------------------------------------
# SET TERRAFORM REQUIREMENTS FOR RUNNING THIS MODULE
# ---------------------------------------------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.9.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = "~> 6.0"
      configuration_aliases = [aws.super_certificate_zone]
    }
    kubernetes = {
      source                = "hashicorp/kubernetes"
      configuration_aliases = [kubernetes.argocd-cluster]
    }
    helm = {
      source                = "hashicorp/helm"
      configuration_aliases = [helm.local-cluster]
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# GET DATA FROM AN EXISTING RESOURCE
# ---------------------------------------------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_iam_session_context" "current" {
  arn = data.aws_caller_identity.current.arn
}

data "aws_eks_cluster" "this" {
  name = var.cluster_id
}

data "aws_eks_cluster_auth" "this" {
  name = data.aws_eks_cluster.this.id
}

provider "kubernetes" {
  alias = "local-cluster"

  host                   = var.cluster_endpoint
  cluster_ca_certificate = base64decode(var.cluster_ca)
  token                  = data.aws_eks_cluster_auth.this.token
}

provider "helm" {
  alias = "local-cluster"

  kubernetes {
    host                   = var.cluster_endpoint
    cluster_ca_certificate = base64decode(var.cluster_ca)
    token                  = data.aws_eks_cluster_auth.this.token
  }
}

provider "random" {
  alias = "local-cluster"
}

locals {
  cluster_type     = var.cluster_type != "" ? var.cluster_type : split("-", var.cluster_name)[1]
  account_id       = data.aws_caller_identity.current.account_id
  current_role_arn = data.aws_iam_session_context.current.issuer_arn
  view_verbs       = ["get", "list", "watch"]
  admin_verbs      = ["delete", "deletecollection", "get", "list", "patch", "create", "update", "watch"]

  app_deploy_repo = {
    "mgmt"   = "ssh://git@gitlab.infrastructure.immuta.io:22/infrastructure/kubernetes/application-deployment.git"
    "cps"    = "ssh://git@gitlab.infrastructure.immuta.io:22/infrastructure/kubernetes/application-deployment.git"
    "saas"   = "ssh://git@gitlab.infrastructure.immuta.io:22/infrastructure/kubernetes/application-deployment.git"
    "shared" = "ssh://git@gitlab.infrastructure.immuta.io:22/infrastructure/kubernetes/application-deployment-infra.git"
    "iim"    = "ssh://git@gitlab.infrastructure.immuta.io:22/infrastructure/kubernetes/application-deployment-infra.git"
    "data"   = "ssh://git@gitlab.infrastructure.immuta.io:22/infrastructure/kubernetes/application-deployment-infra.git"
  }

  app_deploy_repo_github = {
    "mgmt"   = "ssh://git@github.com:22/immuta/application-deployment.git"
    "cps"    = "ssh://git@github.com:22/immuta/application-deployment.git"
    "saas"   = "ssh://git@github.com:22/immuta/application-deployment.git"
    "shared" = "ssh://git@github.com:22/immuta/application-deployment-infra.git"
    "iim"    = "ssh://git@github.com:22/immuta/application-deployment-infra.git"
    "data"   = "ssh://git@github.com:22/immuta/application-deployment-infra.git"
  }
}


# ---------------------------------------------------------------------------------------------------------------------
# MODULE PARAMETERS
# These variables are expected to be passed in by the operator when calling this terraform module.
# ---------------------------------------------------------------------------------------------------------------------

# ---------------------------------------------------------------------------------------------------------------------
# REQUIRED PARAMETERS
# These variables must be set.
# ---------------------------------------------------------------------------------------------------------------------
variable "cluster_name" {
  description = "Cluster name for the EKS cluster"
  type        = string
}

variable "cluster_version" {
  description = "Cluster version for the EKS cluster"
  type        = string
}

variable "env" {
  description = "Environment where the cluster is"
  type        = string
}

variable "account_name" {
  description = "Account name where the cluster is"
  type        = string
}

variable "global_segment" {
  description = "Global segment for the cluster, i.e. na, eu, ap"
  type        = string
  default     = ""
}

variable "region" {
  description = "Region where the cluster is"
  type        = string
}

variable "vpc_id" {
  description = "VPC in which to deploy the cluster"
  type        = string
}

variable "subnet_ids" {
  description = "List of subnets to deploy the cluster into"
  type        = list(string)
}

variable "cluster_endpoint" {
  description = "Endpoint for the cluster from the EKS CLUSTER module"
  type        = string
}

variable "cluster_ca" {
  description = "Certificate Authority for the cluster"
  type        = string
}

variable "cluster_oidc_provider_issuer" {
  description = "ODIC Provider Issuer for the current working cluster"
  type        = string
}

variable "cluster_id" {
  description = "ID of the working cluster (should be the same as the cluster name)"
  type        = string
}

variable "cluster_oidc_provider_arn" {
  description = "OIDC Provider ARN for the current working cluster"
  type        = string
}
# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These variables are configurable, but have reasonable defaults set.
# ---------------------------------------------------------------------------------------------------------------------
variable "cluster_type" {
  description = "The type of cluster, i.e. saas, mgmt, cps, will default to extracting the type from the cluster name"
  type        = string
  default     = ""
}

variable "cluster_clustermesh_id" {
  description = "Cluster ID for clustermesh (must be set for ClusterMesh)"
  type        = number
  default     = 0
}

variable "cluster_worker_sg" {
  description = "Security Group for worker nodes"
  type        = string
  default     = ""
  validation {
    condition     = var.cluster_worker_sg == "" && local.cilium_enabled && var.cluster_mesh_enabled ? false : true
    error_message = "cluster_worker_sg variable must be set when cilium and clustermesh is enabled"
  }
}

variable "tags" {
  description = "Map of key-value pairs to tag created resources with."
  type        = map(any)
  default     = {}
}

variable "vault_endpoint" {
  description = "Endpoint for vault, used in helm values for vault sidecar injector"
  type        = string
  default     = "https://vault.infrastructure.immuta.io:8200"
}

